{
  "title": "The Mirror Bridge Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a cracked map of the ruined city.",
      "visual_description": "Mara the Cartographer kneels on a stone floor, unrolling a parchment map under flickering candlelight; ink stains her coat as she traces a route through collapsed towers.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Glass Diver steps through a shattered window into the city.",
      "visual_description": "Glass Diver emerges from a reflection in a broken window, diving helmet gleaming, coat reflecting the distant glow of burning torches.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "Oracle Lamp warns of a cursed tower ahead.",
      "visual_description": "The Oracle Lamp sits on a fallen column, its single eye flickering as it speaks; shadows stretch behind it from the tower's silhouette.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox scouts the castle gates and returns.",
      "visual_description": "Tin Fox scurries across rubble, key-wind tail spinning, blue glass eyes scanning the iron gates before darting back to the group.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Mara leads the party through an old market square.",
      "visual_description": "Mara gestures forward under torn royal banners hanging from empty stalls; broken crates and faded cloth scatter the square.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Armored patrols march past a collapsed fountain.",
      "visual_description": "A line of armored figures clanks through the square, their visors down, ignoring the overturned fountain and scattered coins.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The group hides in a ruined bakery as patrols pass.",
      "visual_description": "Inside a roofless bakery, Glass Diver presses against a sooty wall; Mara peers through a crack; Tin Fox freezes, gears silent.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Oracle Lamp reveals a secret passage under a statue.",
      "visual_description": "Oracle Lamp casts light on a stone statue's base, revealing a hidden trapdoor; its eye narrows as it whispers instructions.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The group descends into a dark tunnel.",
      "visual_description": "Mara leads down stone steps, compass glowing faintly; Glass Diver's helmet reflects torchlight; Tin Fox clicks ahead.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Sleeping Tax Collector snores in a collapsed office.",
      "visual_description": "A dusty room with a ledger-stuffed desk; the Sleeping Tax Collector dozes, head on a paper pillow, stamped papers stuck to sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Mara tries to wake the Tax Collector for a map key.",
      "visual_description": "Mara shakes the sleeping figure while Oracle Lamp hovers close; Tin Fox sniffs the papers; Glass Diver watches the door.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Glass Diver swims through a mirror into a locked room.",
      "visual_description": "Glass Diver presses a hand to an ornate mirror, surface rippling as he steps through into a chamber with a glowing door.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox disarms a trap near the magic door.",
      "visual_description": "Tin Fox's tail spins as its paws deftly unpick a pressure plate; blue eyes reflect runes on the stone door.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The magic door opens to a courtyard with a bridge.",
      "visual_description": "The stone door grinds open, revealing a moonlit courtyard and a narrow stone bridge spanning a dry moat.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Armored figures block the bridge entrance.",
      "visual_description": "Two armored figures stand at the bridge's far end, weapons drawn; shadows pool beneath the arches.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "Oracle Lamp blinds the armored figures with a flash.",
      "visual_description": "Oracle Lamp flares with brilliant light, its eye blazing; the armored figures stumble, hands to their visors.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The group races across the bridge.",
      "visual_description": "Glass Diver, Mara, Tin Fox, and Oracle Lamp sprint across the stone bridge, broken banners flapping in the wind below.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the mist beyond the city.",
      "visual_description": "The group reaches the far side, gasping; behind them the ruined city fades into fog; Tin Fox's tail ticks slowly.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ]
}

